with authored(stable_key,p) as (
 values
 ('rspp-aspp:rspp_aspp_b:ud1', $json${"summary":"Usare tecniche di valutazione e analisi degli eventi per trasformare evidenze, incidenti e near miss in decisioni di prevenzione verificabili.","detail":"La valutazione non coincide con assegnare un numero a una matrice. Si definiscono campo di analisi, pericoli, persone e attività esposte, condizioni normali/anomale/emergenziali, dati disponibili e incertezze; poi si sceglie una tecnica coerente con il problema. Nell’analisi degli incidenti si ricostruiscono fatti, barriere mancanti o inefficaci e cause organizzative senza fermarsi all’errore dell’operatore.","focus":["Definire scopo e confini prima di scegliere il metodo","Separare fatti, ipotesi e giudizi","Considerare variabilità, esposizione e condizioni non routinarie","Tradurre l’analisi in misure, responsabili, tempi e verifica di efficacia"],"risks":["Usare il punteggio della matrice come verità assoluta","Fermarsi alla causa immediata o alla colpa individuale","Ignorare near miss e segnali deboli","Confondere assenza di infortuni con controllo del rischio"],"prevention":["Raccogliere evidenze da lavoro reale, dati ed eventi","Scegliere tecniche proporzionate a complessità e incertezza","Verificare ipotesi con lavoratori, preposti e competenze tecniche","Riesaminare la valutazione dopo cambiamenti o nuove evidenze"],"procedure":["Definisci attività, confini e decisione da supportare","Raccogli dati, osservazioni, anomalie, incidenti e near miss","Identifica pericoli, esposti, barriere esistenti e scenari","Scegli e applica una tecnica di analisi coerente","Prioritizza misure secondo efficacia e fattibilità senza perdere la gerarchia preventiva","Assegna owner, scadenza, indicatore e riesame"],"scenario":"Un carrello incrocia un pedone in un varco cieco: nessun urto, ma frenata d’emergenza. L’analisi deve andare oltre «disattenzione» e verificare layout, flussi, visibilità, regole, carichi di lavoro e barriere.","case":"Tre near miss simili sono stati chiusi con richiami verbali. Quali evidenze servono per capire se la causa dominante è comportamentale, tecnica o organizzativa?","question":"Perché una matrice di rischio, da sola, non dimostra che la valutazione sia adeguata?","question_explanation":"Perché il valore numerico dipende da ipotesi, scala e qualità dei dati: l’adeguatezza deriva soprattutto dalla corretta identificazione degli scenari, dall’esposizione reale e dalla scelta di misure efficaci.","teacher_expansion":["Fai distinguere pericolo, evento, danno, esposizione e barriera.","Usa un near miss e costruisci una timeline dei fatti prima delle cause.","Confronta due metodi di analisi e chiedi quale decisione supportano meglio.","Chiudi con una misura e chiedi come provarne l’efficacia dopo 30 giorni."],"teacher_activity":"Gruppi da 3: ricostruire un evento, individuare almeno tre barriere e proporre una misura tecnica, una organizzativa e una procedurale con indicatore.","common_errors":["Partire dal metodo invece che dalla domanda","Cercare subito un colpevole","Non esplicitare incertezze e dati mancanti","Chiudere l’azione senza verifica di efficacia"],"takeaway":"Una buona analisi rende esplicito perché il rischio esiste, quali barriere devono funzionare e come verificare che la misura scelta cambi davvero il lavoro.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","inail-condivido-near-miss","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"modello-farfalla-rischio.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Dopo un near miss, qual è la prima scelta metodologica corretta?","answers":["Ricostruire i fatti e le barriere prima di attribuire cause.","Assegnare subito un richiamo all’operatore.","Aumentare il punteggio della matrice senza altre evidenze.","Chiudere perché non ci sono stati danni."],"correct":0,"explanation":"L’analisi efficace parte da evidenze e barriere; la causa non va decisa prima della ricostruzione.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud2', $json${"summary":"Leggere l’organizzazione dei processi produttivi e del lavoro come sistema di interfacce, vincoli e cambiamenti che modifica l’esposizione ai rischi.","detail":"Layout, turni, manutenzione, appalti, produzione snella, just in time, automazione, lavoro agile e nuove tecnologie cambiano attività, tempi, flussi e responsabilità. Il compito di RSPP/ASPP è rendere visibili le interdipendenze tra processo nominale e lavoro reale, anticipando i rischi introdotti dalle modifiche.","focus":["Mappare processo, fasi, persone, materiali, mezzi e interfacce","Confrontare lavoro prescritto e lavoro reale","Valutare cambi organizzativi e tecnologici prima dell’avvio","Integrare sicurezza, manutenzione, qualità, produzione e appalti"],"risks":["Ottimizzare tempi produttivi scaricando rischio sugli operatori","Modificare layout o turni senza riesame dei rischi","Automatizzare una fase creando nuove interfacce uomo-macchina","Affidarsi a procedure che non descrivono deviazioni reali"],"prevention":["Usare mappe di processo e sopralluoghi con chi svolge il lavoro","Inserire la valutazione H&S nel change management","Definire responsabilità e criteri di escalation nelle interfacce","Monitorare indicatori di carico, anomalie, manutenzione e work-around"],"procedure":["Disegna il flusso dall’ingresso materiali all’uscita del prodotto/servizio","Segna attività simultanee, interfacce, picchi, appalti e manutenzioni","Rileva differenze tra procedura e lavoro reale","Valuta effetti del cambiamento su persone, mezzi, tempi e spazi","Definisci controlli prima del go-live e responsabilità","Verifica sul campo dopo l’avvio e correggi deviazioni"],"scenario":"Una linea viene automatizzata e il personale passa da conduzione a presidio, sblocco e manutenzione di primo livello: diminuisce un’esposizione ma aumentano accessi in zona macchina e pressione per ripristinare rapidamente.","case":"Il nuovo layout riduce i metri percorsi dai materiali ma crea un incrocio tra muletti e addetti manutenzione. Come si rivaluta il processo?","question":"Qual è il segnale più utile che il processo reale non coincide più con quello valutato?","question_explanation":"La presenza sistematica di deviazioni, scorciatoie, attese, riavvii o work-around mostra che vincoli e condizioni operative sono cambiati e che la valutazione va confrontata con il lavoro reale.","teacher_expansion":["Fai disegnare una SIPOC semplificata o una mappa di flusso con punti di rischio.","Mostra come un KPI di produttività può creare pressione indesiderata.","Collega smart working e coworking a ergonomia, organizzazione e gestione delle emergenze.","Chiedi quali cambiamenti devono attivare un riesame preventivo."],"teacher_activity":"Mappare un processo noto ai partecipanti e segnare tre interfacce in cui una decisione di un reparto modifica il rischio di un altro.","common_errors":["Valutare reparti isolati e non le interfacce","Coinvolgere H&S a modifica già decisa","Confondere automazione con eliminazione del rischio","Non verificare il processo dopo il go-live"],"takeaway":"Il rischio segue il processo reale: ogni modifica a flussi, tempi, tecnologia o responsabilità deve avere un riesame prima e una verifica dopo.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","inail-sgsl","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"idea-safety-system.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"organigramma-sicurezza.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"idea-safety-system.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Una modifica di layout è pronta ma H&S non è stata coinvolta. Cosa fare?","answers":["Valutare gli impatti prima del go-live e definire controlli/verifica.","Avviare e aggiornare il DVR a fine anno.","Limitarsi a informare gli addetti.","Aggiungere cartelli dopo l’avvio."],"correct":0,"explanation":"Il cambiamento deve essere valutato prima dell’introduzione e poi verificato sul campo.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud3', $json${"summary":"Valutare ambienti e luoghi di lavoro osservando requisiti, uso reale, flussi, manutenzione e condizioni che possono trasformare uno spazio apparentemente idoneo in un rischio.","detail":"Il luogo di lavoro va letto come sistema: accessi, vie di circolazione, pavimenti, scale, aperture, illuminazione, aerazione, microclima, servizi, depositi, manutenzioni, emergenze e presenza di persone con esigenze diverse. La conformità iniziale non sostituisce il controllo delle condizioni d’uso.","focus":["Distinguere requisiti strutturali da condizioni operative","Osservare flussi pedonali, mezzi, materiali e manutentori","Verificare che vie di esodo e accessi restino utilizzabili","Gestire degrado, modifiche temporanee e interferenze"],"risks":["Uscite o passaggi progressivamente ostruiti","Pavimenti danneggiati, scivolosi o con dislivelli non gestiti","Depositi provvisori che diventano permanenti","Manutenzioni che alterano percorsi, illuminazione o ventilazione"],"prevention":["Ispezioni per zone con criteri osservabili","Segnalazione e presa in carico delle anomalie con priorità","Housekeeping e regole di deposito integrate nel processo","Riesame dopo lavori, variazioni di layout o destinazione d’uso"],"procedure":["Dividi il sito in zone e percorsi","Rileva persone presenti, attività e flussi","Controlla condizioni strutturali e d’uso","Classifica anomalie per gravità e urgenza","Definisci misura provvisoria e correzione definitiva","Verifica chiusura sul posto e aggiorna valutazione/procedure se necessario"],"scenario":"Un corridoio di esodo è formalmente dimensionato correttamente ma durante i picchi viene usato per pallet in attesa: il rischio nasce dall’uso reale, non dal disegno originario.","case":"Durante un sopralluogo trovi pavimento bagnato, illuminazione insufficiente e un’uscita parzialmente occupata. Quali azioni sono immediate e quali strutturali?","question":"Perché una checklist di conformità non basta per valutare un luogo di lavoro?","question_explanation":"Perché fotografa requisiti attesi, mentre il rischio dipende anche da uso, manutenzione, flussi, occupazione temporanea e deviazioni che cambiano nel tempo.","teacher_expansion":["Fai leggere una planimetria e aggiungere flussi reali.","Confronta anomalia immediatamente rimovibile e difetto strutturale.","Chiedi come si gestisce una misura compensativa temporanea.","Collega sopralluogo, segnalazione, owner e verifica di chiusura."],"teacher_activity":"Su una planimetria semplificata, individuare percorsi persone/mezzi, punti ciechi, depositi e vie di esodo; formulare cinque osservazioni verificabili.","common_errors":["Limitarsi alla conformità documentale","Segnalare senza assegnare owner e scadenza","Accettare misure provvisorie senza limite temporale","Non riesaminare spazi dopo modifiche"],"takeaway":"Un luogo è sicuro solo se requisiti e condizioni d’uso restano coerenti nel tempo.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"piramide-pericoli.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"piramide-pericoli.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Un’uscita di emergenza viene usata regolarmente come area di attesa pallet. Qual è la priorità?","answers":["Ripristinare subito la fruibilità e correggere la causa organizzativa del deposito.","Aggiungere un cartello più grande.","Aspettare la prossima ispezione periodica.","Aggiornare solo la planimetria."],"correct":0,"explanation":"La condizione reale compromette una barriera essenziale: va rimossa e va eliminata la causa che la rende ricorrente.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud4', $json${"summary":"Integrare prevenzione incendi, atmosfere esplosive e gestione delle emergenze in una lettura unica di sorgenti, combustibili, condizioni di innesco, propagazione e capacità di risposta.","detail":"La valutazione parte dalle condizioni reali: materiali combustibili o infiammabili, processi e sorgenti di innesco, ventilazione, possibili atmosfere esplosive, compartimentazioni, impianti, esodo, allarme e organizzazione dell’emergenza. Le misure devono funzionare anche in manutenzione, fermata, avviamento e attività non routinarie.","focus":["Individuare scenari credibili e non solo adempimenti","Prevenire formazione/innesco e limitare conseguenze","Integrare gestione cambiamenti e lavori a caldo","Verificare esodo, allarme, presidio e coordinamento emergenze"],"risks":["Accumulo di combustibili o rilascio di sostanze infiammabili","Sorgenti di innesco non controllate durante manutenzioni","Classificazioni ATEX non aggiornate dopo modifica di processo","Piano di emergenza non coerente con persone, turni e layout reali"],"prevention":["Ridurre inventari e sorgenti di rilascio dove possibile","Controllare sorgenti di innesco e attività temporanee","Mantenere liberi e riconoscibili i percorsi di esodo","Esercitare ruoli e comunicazioni con scenari realistici"],"procedure":["Definisci sostanze/materiali, processo e scenari","Individua rilascio, innesco, propagazione e persone esposte","Verifica prevenzione, protezioni e condizioni ATEX pertinenti","Controlla gestione lavori non routinari e manutenzioni","Verifica allarme, esodo, ruoli e interfacce con soccorsi","Registra criticità, misura temporanea, owner e riesame"],"scenario":"Durante una manutenzione viene usato un utensile non previsto vicino a una zona con possibile rilascio di vapori: la gestione del lavoro temporaneo diventa barriera essenziale.","case":"Il layout non è cambiato, ma è aumentata la quantità di prodotto infiammabile stoccato e sono stati spostati alcuni addetti. Cosa va rivalutato?","question":"Perché il piano di emergenza non può essere separato dalla valutazione del rischio incendio/esplosione?","question_explanation":"Perché ruoli, allarme, esodo e risposta devono essere costruiti sugli scenari e sulle persone realmente esposte; un piano generico può fallire proprio nello scenario critico.","teacher_expansion":["Costruisci con la classe triangolo combustibile/innesco/condizioni favorevoli e relative barriere.","Usa un permesso di lavoro a caldo come esempio di controllo organizzativo.","Distingui prevenzione dell’evento e mitigazione delle conseguenze.","Chiedi quali prove osservabili dimostrano che il piano è praticabile."],"teacher_activity":"Analizzare uno scenario con rilascio e innesco: individuare barriere preventive, protettive, organizzative e una condizione di STOP.","common_errors":["Ridurre il tema a estintori e cartelli","Trattare ATEX come documento statico","Ignorare manutenzioni e lavori temporanei","Fare prove di emergenza senza debrief e azioni correttive"],"takeaway":"Incendio, esplosione ed emergenza si governano come catena di barriere: prevenire, rilevare, contenere, evacuare e apprendere dalle prove.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","vvf-materiali-antincendio","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"modello-farfalla-rischio.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"stop-segnala-ripristina.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"In un’area con possibile rilascio infiammabile cambia una manutenzione. Qual è l’azione corretta?","answers":["Rivalutare scenario, sorgenti di innesco e condizioni operative prima del lavoro.","Fare affidamento sugli estintori presenti.","Procedere se il lavoro dura pochi minuti.","Chiedere solo maggiore attenzione."],"correct":0,"explanation":"Le attività temporanee possono cambiare le condizioni di incendio/esplosione e vanno gestite prima dell’avvio.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud5', $json${"summary":"Valutare i rischi infortunistici partendo dalle energie pericolose e dalle interazioni tra persone, macchine, impianti, sollevamento, trasporti e lavori in quota.","detail":"Macchine, impianti elettrici, organi in movimento, carichi sospesi, veicoli e dislivelli generano scenari ad alta conseguenza. L’analisi deve considerare tutte le fasi: uso normale, regolazione, pulizia, sblocco, manutenzione, accesso e recupero anomalie, privilegiando eliminazione e protezioni collettive prima di affidarsi al comportamento.","focus":["Individuare energie, movimenti e zone di pericolo","Analizzare fasi non routinarie e recupero anomalie","Separare persone e mezzi quando tecnicamente possibile","Verificare idoneità di attrezzature, protezioni e procedure"],"risks":["Bypass di ripari per recuperare tempi","Intervento su energia non isolata","Transito sotto carichi o in aree di manovra","Lavoro in quota improvvisato o con accesso inadeguato"],"prevention":["Progettare protezioni e segregazioni efficaci","Definire isolamento sicuro delle energie prima dell’intervento","Gestire viabilità e separazione pedoni-mezzi","Pianificare accesso, protezioni collettive e recupero per lavori in quota"],"procedure":["Identifica energia/pericolo e fase di lavoro","Osserva accessi, interazioni e deviazioni prevedibili","Verifica protezioni tecniche e loro reale utilizzabilità","Definisci isolamento, autorizzazioni e controlli per fasi critiche","Gestisci traffico, sollevamento e quota con aree e responsabilità chiare","Prova sul campo la misura e raccogli anomalie"],"scenario":"Una macchina si inceppa più volte a turno; l’operatore apre un riparo per sbloccarla rapidamente. Il problema non è solo il gesto: frequenza del guasto, accessibilità e pressione produttiva rendono prevedibile la deviazione.","case":"Un carrello con carico voluminoso deve attraversare un’area pedonale. Quali misure eliminano o riducono l’interazione prima di ricorrere a segnali e attenzione?","question":"Quale fase di una macchina merita spesso più attenzione dell’uso normale?","question_explanation":"Sblocco, pulizia, regolazione e manutenzione spesso richiedono accesso a zone normalmente protette e possono esporre a energie residue o riavvii inattesi.","teacher_expansion":["Usa il concetto di energia per unificare meccanico, elettrico, gravità e pressione.","Analizza una dinamica Infor.MO senza colpevolizzare l’infortunato.","Fai costruire una gerarchia di controlli per traffico interno.","Collega lavori in quota a pianificazione dell’accesso e dell’emergenza."],"teacher_activity":"Da una foto/scheda di macchina o carrello, elencare fasi normali e non routinarie, energie, persone esposte e tre barriere verificabili.","common_errors":["Valutare solo il ciclo automatico","Usare DPI come prima risposta","Affidarsi a cartelli dove serve separazione fisica","Non considerare guasti e manutenzione"],"takeaway":"Gli infortuni gravi spesso avvengono alle interfacce e nelle fasi anomale: progettare la barriera prima di chiedere maggiore attenzione.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","inail-informo-carrelli-21","inail-quaderni-cantieri","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"piramide-pericoli.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"piramide-pericoli.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"modello-farfalla-rischio.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Una macchina si inceppa spesso e l’operatore accede alla zona pericolosa. Qual è la misura più robusta?","answers":["Eliminare la causa del guasto e rendere sicuro l’accesso/isolamento.","Ricordare di stare più attenti.","Aggiungere un adesivo di pericolo.","Fornire guanti più resistenti."],"correct":0,"explanation":"La prevenzione deve agire sulla causa e sull’energia pericolosa, non dipendere principalmente dal comportamento.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud6', $json${"summary":"Valutare ergonomia, movimentazione manuale e videoterminali adattando compito, organizzazione, strumenti e ambiente alle capacità umane invece di chiedere alla persona di compensare il sistema.","detail":"Il rischio ergonomico nasce dalla combinazione di forza, postura, ripetitività, durata, recupero, presa, distanze, caratteristiche del carico e organizzazione. Per i VDT contano anche postura, regolazioni, disposizione, pause/cambi di attività, ambiente e progettazione del compito. La valutazione deve usare metodi appropriati e dati del lavoro reale.","focus":["Scomporre il compito e descrivere esposizione reale","Ridurre forza, distanza, frequenza e posture incongrue alla fonte","Progettare attrezzature e layout per la variabilità delle persone","Integrare tempi, rotazioni e recupero senza usarli per compensare un cattivo design"],"risks":["Sollevamenti con torsione o carico lontano dal corpo","Compiti ripetitivi senza recupero adeguato","Postazioni non regolabili o regolate male","Valutazioni medie che ignorano picchi e variabilità"],"prevention":["Eliminare movimentazioni non necessarie e usare ausili idonei","Ridisegnare altezze, distanze e prese","Alternare compiti realmente diversi quando utile","Formare sull’uso delle regolazioni dopo aver migliorato il sistema"],"procedure":["Osserva il ciclo completo e i picchi","Raccogli peso/forza, frequenza, durata, distanze, posture e recuperi pertinenti","Scegli il metodo di valutazione coerente","Individua determinanti tecnici e organizzativi modificabili","Progetta e prova la soluzione con gli utilizzatori","Rivaluta esposizione e usabilità dopo l’intervento"],"scenario":"Nel picking, il peso medio dei colli è modesto ma i prelievi più frequenti sono a pavimento e lontani dal corpo: la media nasconde il vero determinante ergonomico.","case":"Una postazione VDT ha sedia regolabile ma il monitor è laterale e il software impone continui cambi finestra. Quali fattori sono hardware e quali organizzativi?","question":"Perché la sola formazione sulla postura non è una misura sufficiente?","question_explanation":"Perché se layout, compito, frequenza o attrezzatura impongono posture sfavorevoli, il comportamento corretto non è sostenibile; occorre modificare il sistema alla fonte.","teacher_expansion":["Fai descrivere un compito in termini di forza-postura-frequenza-durata-recupero.","Confronta una misura tecnica con una rotazione organizzativa.","Mostra perché il peso del carico da solo non descrive il rischio.","Per VDT, separa regolazione della postazione e progettazione del lavoro."],"teacher_activity":"Ridisegnare un’attività di picking o una postazione VDT indicando modifica, fattore di rischio ridotto e prova di efficacia.","common_errors":["Basarsi solo sul peso","Prescrivere postura ideale senza cambiare il compito","Usare rotazioni tra compiti con la stessa esposizione","Non coinvolgere gli utilizzatori nella prova"],"takeaway":"L’ergonomia efficace modifica il lavoro: riduce l’esposizione prima di affidarsi alla capacità individuale di adattarsi.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"piramide-pericoli.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"idea-safety-system.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"piramide-pericoli.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Un compito impone torsione del busto a ogni ciclo. Qual è la priorità?","answers":["Ridisegnare posizione di carico/scarico e layout.","Fare un corso sulla postura corretta.","Cambiare operatore ogni settimana.","Aggiungere una pausa a fine turno."],"correct":0,"explanation":"Se il compito impone la postura, la soluzione primaria è modificare il compito o il layout.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud7', $json${"summary":"Valutare e gestire i rischi psicosociali come rischi organizzativi, distinguendo fattori di lavoro, eventi sentinella e percezioni da diagnosi individuali.","detail":"Stress lavoro-correlato, aggressioni, molestie e fenomeni di burn-out richiedono una lettura di carichi, autonomia, ruolo, supporto, cambiamenti, relazioni, turni, contatto con il pubblico e segnali organizzativi. L’RSPP/ASPP contribuisce al processo di valutazione e prevenzione senza trasformarsi in clinico o investigatore delle persone.","focus":["Usare dati organizzativi e coinvolgimento dei lavoratori","Distinguere fattori di rischio da effetti individuali","Gestire aggressioni e molestie con prevenzione, segnalazione e supporto","Riesaminare dopo riorganizzazioni e segnali significativi"],"risks":["Ridurre lo stress a fragilità personale","Usare questionari senza analizzare l’organizzazione","Ignorare sottosegnalazione di aggressioni/molestie","Raccogliere dati sensibili senza necessità o governance"],"prevention":["Agire su carichi, ruoli, autonomia, supporto e processi","Definire canali di segnalazione e risposta chiari","Formare ruoli esposti a conflitto/aggressione con misure organizzative","Monitorare indicatori e verificare l’effetto delle azioni"],"procedure":["Definisci gruppi omogenei/contesti e cambiamenti rilevanti","Raccogli indicatori ed evidenze organizzative","Analizza fattori di contenuto e contesto del lavoro","Coinvolgi persone e rappresentanze con metodo tracciabile","Definisci interventi primari sull’organizzazione e supporti","Monitora indicatori, feedback e necessità di approfondimento"],"scenario":"Un servizio al pubblico aumenta target e riduce organico; crescono assenze, turnover e aggressioni verbali. Rispondere solo con un corso di resilienza lascia invariati i determinanti.","case":"Due reparti hanno lo stesso carico numerico, ma uno ha autonomia e supporto elevati e l’altro continui cambi di priorità. Come cambia l’analisi?","question":"Perché un questionario, da solo, non conclude la valutazione del rischio stress lavoro-correlato?","question_explanation":"Perché deve essere integrato nel processo con indicatori, fattori organizzativi, partecipazione e azioni; il punteggio non sostituisce l’analisi delle cause modificabili.","teacher_expansion":["Usa la metodologia INAIL come struttura di processo, non come semplice modulo.","Distingui prevenzione primaria, gestione dell’evento e supporto successivo.","Fai discutere privacy e minimizzazione dei dati.","Collega cambi organizzativi e riesame della valutazione."],"teacher_activity":"Su un caso di riorganizzazione, classificare segnali, fattori di rischio, azioni sull’organizzazione e indicatori per il follow-up.","common_errors":["Medicalizzare problemi organizzativi","Confondere soddisfazione con valutazione del rischio","Intervenire solo sulla persona","Non verificare l’efficacia delle azioni"],"takeaway":"Nei rischi psicosociali la domanda chiave è: quale caratteristica modificabile dell’organizzazione sta producendo esposizione?","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","inail-stress-methodology-2025","inail-violence-work-2025","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"idea-safety-system.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"organigramma-sicurezza.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"idea-safety-system.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"organigramma-sicurezza.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Aumentano assenze e aggressioni dopo una riorganizzazione. Qual è la risposta iniziale più utile?","answers":["Analizzare fattori organizzativi, indicatori e condizioni di lavoro.","Inviare tutti a un corso di resilienza.","Chiedere chi è più fragile.","Ignorare finché non arriva una denuncia."],"correct":0,"explanation":"I segnali vanno collegati ai determinanti organizzativi modificabili e gestiti con un processo di valutazione.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud8', $json${"summary":"Gestire gli agenti fisici attraverso una catena coerente: sorgente, propagazione, esposizione, misura tecnica, organizzazione e verifica strumentale quando necessaria.","detail":"Rumore, vibrazioni, campi elettromagnetici e radiazioni ottiche artificiali richiedono identificazione delle sorgenti, tempi/modalità di esposizione, persone particolarmente sensibili quando previsto, dati tecnici e misure. La scelta dello strumento di misura viene dopo la definizione della domanda valutativa e deve supportare decisioni concrete.","focus":["Censire sorgenti e scenari di esposizione","Distinguere emissione della sorgente ed esposizione della persona","Privilegiare riduzione alla fonte, isolamento e organizzazione","Usare misure e dati tecnici con competenza e incertezza esplicita"],"risks":["Misurare senza sapere quale decisione supportare","Usare dati di targa fuori dal contesto reale","Affidarsi solo ai DPI","Non rivalutare dopo modifica di macchina, tempi o layout"],"prevention":["Scegliere attrezzature/processi a minore emissione","Separare o schermare sorgenti quando tecnicamente possibile","Ridurre tempi di esposizione come misura complementare","Manutenere e verificare le misure tecniche"],"procedure":["Censisci sorgenti, attività e persone esposte","Definisci scenari, tempi e condizioni operative","Raccogli dati affidabili e stabilisci se servono misure strumentali","Valuta esposizione con metodo pertinente","Definisci interventi alla fonte, sul percorso e organizzativi","Verifica efficacia e aggiorna dopo cambiamenti"],"scenario":"Una nuova smerigliatrice ha dati dichiarati migliori, ma viene usata per più ore e su materiale diverso: non è possibile concludere l’esposizione dal solo dato del costruttore.","case":"Un reparto riduce rumore medio ma introduce picchi durante pulizia e manutenzione. Come va organizzata la valutazione?","question":"Qual è l’errore nel partire subito dalla misurazione strumentale?","question_explanation":"Senza definire sorgenti, scenari, tempi e decisione da supportare si rischia di misurare la condizione sbagliata e ottenere dati formalmente precisi ma poco rappresentativi.","teacher_expansion":["Disegna sorgente-percorso-persona e associa misure a ciascun livello.","Confronta dato di targa, stima preliminare e misura sul campo.","Chiedi cosa cambia se raddoppia il tempo di uso o cambia il materiale.","Evidenzia il ruolo della competenza tecnica nella misura e interpretazione."],"teacher_activity":"Per una sorgente fisica scelta, costruire il piano minimo di raccolta dati prima di chiedere una misurazione.","common_errors":["Confondere emissione ed esposizione","Misurare una giornata non rappresentativa","Partire dai DPI","Dimenticare esposizioni di manutentori e attività anomale"],"takeaway":"Una misura è utile quando rappresenta lo scenario giusto e porta a una decisione di prevenzione.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"piramide-pericoli.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"modello-farfalla-rischio.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"piramide-pericoli.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Prima di una campagna di misure di rumore, cosa serve?","answers":["Definire sorgenti, scenari, tempi e decisione che i dati devono supportare.","Comprare il fonometro più costoso.","Misurare una posizione casuale per un’ora.","Distribuire DPI e rinviare la valutazione."],"correct":0,"explanation":"La misura deve rappresentare l’esposizione reale e rispondere a una domanda valutativa definita.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud9', $json${"summary":"Valutare agenti chimici, cancerogeni/mutageni e amianto partendo da inventario, pericolosità, modalità d’uso, vie di esposizione e possibilità di eliminazione o sostituzione.","detail":"La scheda di dati di sicurezza è una fonte importante ma non descrive da sola l’esposizione. Servono quantità, concentrazioni, temperature, frequenza, durata, modalità di trasferimento, emissioni, manutenzioni, pulizie e incidenti. Per agenti ad alta pericolosità la strategia deve spingere verso eliminazione/sostituzione, sistemi chiusi e minimizzazione dell’esposizione; l’amianto richiede gestione specialistica e rispetto della disciplina dedicata.","focus":["Mantenere inventario coerente con prodotti realmente presenti","Leggere SDS insieme al processo e alle vie di esposizione","Valutare sostituzione e contenimento prima dei DPI","Gestire sversamenti, manutenzioni e rifiuti contaminati come scenari"],"risks":["SDS non aggiornata o non corrispondente al prodotto","Travasi in contenitori non identificati","Uso aperto dove sarebbe possibile contenimento","Pulizia/manutenzione con esposizione sottovalutata"],"prevention":["Eliminare o sostituire quando tecnicamente possibile","Ridurre quantità e sistemi aperti","Usare aspirazione/contenimento e procedure di igiene","Definire emergenza, decontaminazione e DPI coerenti con il rischio residuo"],"procedure":["Censisci sostanze, miscele, agenti generati dal processo e attività","Raccogli classificazione, SDS e dati di processo","Mappa vie, durata e intensità potenziale di esposizione","Valuta eliminazione/sostituzione e misure collettive","Definisci controlli per uso, stoccaggio, travaso, manutenzione ed emergenza","Verifica esposizione e aggiorna inventario/valutazione a ogni modifica"],"scenario":"Un solvente viene sostituito con un prodotto «meno pericoloso», ma il nuovo ciclo richiede temperatura maggiore e uso più frequente: la sostituzione va valutata sul rischio complessivo, non sul pittogramma.","case":"In magazzino trovi tre contenitori secondari senza etichetta e una SDS vecchia. Quali sono le prime azioni e quali informazioni servono prima di riavviare l’uso?","question":"Perché la SDS non è una valutazione del rischio?","question_explanation":"Descrive proprietà, pericoli e indicazioni del prodotto, ma il rischio dipende da come, quanto, dove e da chi viene usato e dalle misure presenti nel processo reale.","teacher_expansion":["Fai costruire inventario → attività → via di esposizione → barriera.","Confronta sostituzione apparente e sostituzione realmente più sicura.","Usa un travaso per discutere etichettatura, ventilazione, sversamento e DPI residui.","Ricorda che l’amianto richiede competenze e percorsi specifici, non improvvisazione."],"teacher_activity":"Dati un prodotto e tre modalità d’uso, individuare come cambia l’esposizione e proporre misure in gerarchia.","common_errors":["Confondere pericolo del prodotto e rischio dell’attività","Usare il DPI come controllo principale","Dimenticare agenti generati dal processo","Non includere pulizia, emergenza e manutenzione"],"takeaway":"Nel rischio chimico il documento accompagna il processo: la prevenzione nasce dal controllo di quantità, rilascio e vie di esposizione.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","inail-primo-soccorso-chimico-2025","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"piramide-pericoli.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"piramide-pericoli.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"modello-farfalla-rischio.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"La SDS di un prodotto è disponibile. Possiamo considerare valutato il rischio?","answers":["No: servono modalità d’uso, quantità, durata, vie di esposizione e misure reali.","Sì, la SDS sostituisce la valutazione.","Sì, se il prodotto ha pochi pittogrammi.","Sì, se gli addetti usano guanti."],"correct":0,"explanation":"La SDS informa sul pericolo del prodotto; il rischio dipende dal contesto e dall’esposizione reale.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud10', $json${"summary":"Valutare gli agenti biologici collegando fonte, via di trasmissione, attività esposta, probabilità di contatto e misure di contenimento, igiene e organizzazione.","detail":"Il rischio biologico non riguarda solo laboratori e sanità: può emergere in rifiuti, acque, animali, manutenzioni, pulizie e attività con potenziale contatto con materiale biologico. La valutazione distingue uso deliberato ed esposizione potenziale, considera classificazione pertinente, procedure, incidenti, igiene, contenimento e sorveglianza sanitaria quando prevista.","focus":["Identificare sorgente e via di esposizione nel processo","Valutare attività ordinarie, incidenti e manutenzioni","Interrompere la catena di esposizione con contenimento e igiene","Gestire punture, schizzi, contaminazioni e altre esposizioni accidentali"],"risks":["Considerare biologico solo ciò che è visibile","Procedure di pulizia che aerosolizzano contaminanti","DPI usati senza corretta rimozione e igiene","Mancata gestione immediata di esposizioni accidentali"],"prevention":["Ridurre contatto e aerosol alla fonte","Separare pulito/sporco e definire flussi","Garantire igiene, contenimento, sanificazione e smaltimento coerenti","Definire gestione post-esposizione e coinvolgimento sanitario competente"],"procedure":["Individua sorgenti e attività con possibile esposizione","Mappa vie di trasmissione e persone esposte","Valuta frequenza, durata, incidenti e condizioni aggravanti","Definisci contenimento, igiene, procedure e DPI residui","Prepara risposta a contaminazione/esposizione accidentale","Verifica applicazione, incidenti e necessità di riesame"],"scenario":"Durante manutenzione di un impianto di acque reflue si apre una linea non completamente drenata: il rischio dipende dalla possibilità di schizzi/aerosol e dalle procedure di isolamento e decontaminazione.","case":"Una squadra di pulizia cambia metodo da panno umido a getto ad alta pressione in un’area contaminabile. Quale nuovo scenario di esposizione compare?","question":"Perché «mettere i guanti» non conclude la gestione del rischio biologico?","question_explanation":"I guanti proteggono solo una via di contatto e possono diventare vettore se usati male; servono controllo della sorgente, flussi, igiene, rimozione corretta e gestione delle esposizioni.","teacher_expansion":["Disegna sorgente-via-ospite e associa barriere.","Distingui esposizione deliberata e potenziale senza ridurre la seconda a rischio minore.","Usa un incidente con schizzo per discutere risposta immediata e tracciabilità.","Collega procedure di pulizia alla possibilità di aerosol."],"teacher_activity":"Per un’attività non sanitaria, costruire catena di esposizione e almeno quattro punti di interruzione.","common_errors":["Limitare il rischio biologico agli ospedali","Usare solo DPI","Non considerare aerosol e superfici contaminate","Non predisporre una procedura post-esposizione"],"takeaway":"La prevenzione biologica funziona quando interrompe la catena di esposizione prima, durante e dopo l’attività.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"modello-farfalla-rischio.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"In una pulizia potenzialmente contaminata si introduce un getto ad alta pressione. Cosa cambia?","answers":["Va rivalutata la possibile generazione di aerosol e l’intera catena di esposizione.","Nulla, perché il prodotto chimico non cambia.","Basta usare guanti più spessi.","Serve solo ridurre il tempo."],"correct":0,"explanation":"Il metodo di lavoro può cambiare la via e l’intensità di esposizione biologica.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud11', $json${"summary":"Gestire attività particolari — ambienti confinati/sospetti di inquinamento, lavori su strada e rifiuti — con autorizzazione, coordinamento e condizioni di STOP adeguate a rischi dinamici e ad alta conseguenza.","detail":"Questi contesti condividono variabilità e interfacce: atmosfera e accesso nei confinati, traffico veicolare nelle attività su strada, sostanze/oggetti/mezzi nella gestione rifiuti. La preparazione del lavoro deve rendere verificabili requisiti, ruoli, condizioni operative, comunicazioni e risposta all’emergenza; nei confinati si applica anche la disciplina specifica di qualificazione.","focus":["Riconoscere quando l’attività ricade in disciplina specialistica","Preparare il lavoro prima dell’accesso o dell’esposizione al traffico","Coordinare committente, impresa, operatori e soccorso","Definire criteri di sospensione non negoziabili"],"risks":["Ingresso in ambiente senza verifica delle condizioni e presidio","Variazione del traffico che rende inefficace la segnalazione predisposta","Rifiuto non caratterizzato o contenitore danneggiato gestito come ordinario","Emergenza improvvisata che espone anche i soccorritori"],"prevention":["Permesso/procedura con verifica pre-attività e durante l’attività","Segregazione, segnalazione e coordinamento coerenti con il traffico reale","Identificazione dei rifiuti e mezzi/attrezzature idonei","Piano di emergenza e recupero praticabile prima di iniziare"],"procedure":["Classifica l’attività e le norme/procedure applicabili","Verifica qualifiche, informazioni, ruoli e coordinamento","Controlla sito, atmosfera/traffico/materiali e condizioni iniziali","Autorizza solo con barriere e soccorso disponibili","Monitora cambiamenti e applica STOP al superamento dei criteri","Chiudi il lavoro, registra anomalie e aggiorna la pianificazione"],"scenario":"Un intervento in vasca è pronto a partire, ma il monitoraggio rileva una condizione diversa da quella prevista: la pressione per rispettare la fermata impianto non modifica il criterio di STOP.","case":"In un cantiere mobile il traffico aumenta improvvisamente e la visibilità peggiora. Chi deve poter sospendere il lavoro e quali condizioni vanno ripristinate?","question":"Qual è l’errore comune che accomuna confinati, strada e rifiuti?","question_explanation":"Trattarli come attività standard anche quando le condizioni possono cambiare rapidamente: serve una preparazione specifica e la capacità di fermare il lavoro quando le barriere previste non sono più valide.","teacher_expansion":["Usa la scheda Infor.MO sui confinati per discutere soccorritori coinvolti negli eventi.","Collega il DI 22/01/2019 alle procedure di segnaletica in presenza di traffico.","Per i rifiuti, parti da identificazione e condizioni del materiale prima della manipolazione.","Fai esplicitare chi ha autorità di STOP in ogni scenario."],"teacher_activity":"Tre gruppi, uno per scenario: definire prerequisiti, STOP, escalation e prova che il lavoro possa iniziare in sicurezza.","common_errors":["Confondere addestramento con autorizzazione automatica","Predisporre emergenza solo sulla carta","Non rivalutare quando cambia il contesto","Lasciare ambiguo chi può fermare l’attività"],"takeaway":"Nelle attività ad alta conseguenza, iniziare è una decisione: se prerequisiti, barriere o soccorso non sono verificati, il lavoro non parte.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","normattiva-dpr177-2011","mlps-di-segnaletica-stradale-2019","inail-informo-confinati-11","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"modello-farfalla-rischio.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"stop-segnala-ripristina.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"procedura-operativa-5-fasi.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Durante un lavoro in ambiente confinato una condizione essenziale non è più verificata. Cosa si fa?","answers":["Si sospende e si ripristinano i prerequisiti prima di riprendere.","Si continua se manca poco.","Decide solo il committente a fine attività.","Si aggiunge un DPI senza rivalutare."],"correct":0,"explanation":"I criteri di STOP servono proprio a impedire che pressione operativa sostituisca i prerequisiti di sicurezza.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb),
 ('rspp-aspp:rspp_aspp_b:ud12', $json${"summary":"Gestire i rischi connessi ad alcol, sostanze stupefacenti e psicotrope distinguendo prevenzione organizzativa, idoneità/sorveglianza sanitaria e tutela della riservatezza.","detail":"Il tema va affrontato per il possibile impatto su vigilanza, coordinazione, giudizio e comportamento sicuro, soprattutto nelle attività in cui un’alterazione può aumentare conseguenze per sé o altri. RSPP/ASPP supporta valutazione, procedure e prevenzione, ma non effettua diagnosi né accertamenti sanitari: i percorsi sanitari spettano ai soggetti competenti nei casi previsti dalla disciplina applicabile.","focus":["Valutare attività e conseguenze di un’eventuale alterazione","Definire procedure per condizioni osservabili di non sicurezza","Separare gestione operativa da diagnosi o giudizi personali","Proteggere riservatezza e coinvolgere medico competente quando pertinente"],"risks":["Affrontare il tema con stigma o accuse","Lasciare al preposto il compito di fare diagnosi","Mancanza di una procedura per allontanare in sicurezza da attività critica","Confondere politica aziendale, obblighi normativi e dati sanitari"],"prevention":["Regole chiare collegate ai compiti e comunicate preventivamente","Supervisione basata su condizioni di sicurezza osservabili","Percorsi di escalation e gestione temporanea dell’attività","Coordinamento con medico competente e HR nei limiti dei rispettivi ruoli"],"procedure":["Individua compiti in cui un’alterazione può aumentare il rischio","Definisci regole, responsabilità e canale di escalation","Forma i ruoli a riconoscere condizioni operative non sicure senza diagnosticare","Sospendi/riassegna in sicurezza l’attività critica quando necessario","Attiva i soggetti sanitari/organizzativi competenti secondo disciplina e procedura","Registra solo le informazioni necessarie e riesamina eventi e misure"],"scenario":"Un addetto a un’attrezzatura mostra difficoltà di coordinazione. Il preposto deve gestire la sicurezza immediata e attivare la procedura, non stabilire la causa sanitaria.","case":"Un responsabile vuole annotare in un registro condiviso il sospetto di assunzione di sostanze. Quali problemi di ruolo, privacy e gestione operativa emergono?","question":"Che cosa deve fare l’RSPP davanti a un possibile caso individuale?","question_explanation":"Deve supportare il sistema e la procedura di sicurezza, non diagnosticare o svolgere accertamenti: la gestione sanitaria appartiene ai soggetti abilitati e le informazioni devono essere trattate con necessità e riservatezza.","teacher_expansion":["Distingui segno osservabile, ipotesi sulla causa e dato sanitario.","Fai costruire una procedura che parta dalla sicurezza del compito.","Evidenzia il ruolo del medico competente nei casi pertinenti.","Discuti come evitare stigma mantenendo ferme le condizioni di sicurezza."],"teacher_activity":"Simulazione: preposto, RSPP e medico competente definiscono cosa ciascun ruolo può fare, cosa non deve fare e quali informazioni può condividere.","common_errors":["Diagnosticare sulla base di comportamento osservato","Raccogliere dati sanitari eccedenti","Non prevedere una soluzione sicura per il turno in corso","Usare il tema solo in chiave disciplinare"],"takeaway":"La priorità è rendere sicura l’attività e attivare i ruoli corretti, senza trasformare la prevenzione in diagnosi o sorveglianza impropria.","source_keys":["mlps-asr-2025","normattiva-dlgs81-vigente","piemonte-indicazioni-formazione-2025","rer-formazione-figure-prevenzione"],"idea_images":[{"file":"organigramma-sicurezza.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"stop-segnala-ripristina.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."},{"file":"procedura-operativa-5-fasi.svg","caption":"Schema didattico SafetyTraining per supportare analisi e decisione."}],"graphic_cards":[{"image":"organigramma-sicurezza.svg","kicker":"SCHEMA AUTORIALE","title":"OSSERVA → DECIDI","text":"Dalla condizione reale alla misura verificabile.","points":["evidenze","scenario","barriere","verifica"]},{"image":"stop-segnala-ripristina.svg","kicker":"LAVORO RSPP/ASPP","title":"PRIMA → DURANTE → DOPO","text":"Prepara, controlla, riesamina.","points":["prerequisiti","controlli","STOP","follow-up"]}],"quiz":{"q":"Un addetto a compito critico appare non in condizioni di operare in sicurezza. Il preposto deve:","answers":["Mettere in sicurezza l’attività e attivare la procedura senza formulare diagnosi.","Diagnosticare la causa e annotarla.","Interrogarlo davanti ai colleghi.","Ignorare finché non avviene un evento."],"correct":0,"explanation":"Il ruolo operativo riguarda la sicurezza immediata e l’escalation; diagnosi e accertamenti competono ai soggetti sanitari previsti.","formative_only":true,"test_builder_excluded":true}}$json$::jsonb)
),
base as (
 select lu.id learning_unit_id,lu.stable_key,v.content,a.p
 from public.learning_units lu
 join public.learning_unit_versions v on v.learning_unit_id=lu.id and v.version_number=1
 join authored a on a.stable_key=lu.stable_key
),
enriched as (
 select learning_unit_id,
   content || p || jsonb_build_object(
     'didactic_version','rspp-aspp-authored-v3',
     'operational',jsonb_build_object(
       'objective',p->>'summary',
       'before',p->'prevention',
       'during',p->'procedure',
       'after',jsonb_build_array('Verifica attuazione ed efficacia della misura.','Traccia criticità aperte, responsabile, scadenza e riesame.'),
       'step_by_step',p->'procedure',
       'if_problem',jsonb_build_array('Se mancano dati essenziali, sospendi la conclusione e attiva l’approfondimento competente.','Se una barriera critica non è disponibile o la condizione reale diverge da quella valutata, applica STOP/escalation.'),
       'stop_conditions',p->'risks',
       'who_to_involve',jsonb_build_array('Datore di lavoro/dirigenti','RSPP/ASPP','Preposti e lavoratori','RLS','Medico competente o competenze specialistiche quando pertinenti'),
       'remember',p->>'takeaway',
       'adaptation','Adattare esempi, criteri e decisioni a DVR, processi, procedure, ruoli e contesto reale.'
     ),
     'quality',jsonb_build_object(
       'teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,
       'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,
       'final_assessment',false,'test_builder_excluded',true
     ),
     'source_audit',jsonb_build_object(
       'status','reviewed','checked_on','2026-10-16',
       'normative_validation','D.Lgs. 81/2008 vigente + Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR; fonti specialistiche dove pertinenti',
       'reuse_policy','facts_reference_and_original_didactic_rewrite'
     ),
     'evidence_sources',(
       select coalesce(jsonb_agg(jsonb_build_object(
         'source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,
         'use',case
           when ts.source_key in ('mlps-asr-2025','normattiva-dlgs81-vigente','normattiva-dpr177-2011','mlps-di-segnaletica-stradale-2019') then 'normative_validation'
           when ts.source_key='piemonte-indicazioni-formazione-2025' then 'official_guidance_cross_check'
           when ts.source_key='rer-formazione-figure-prevenzione' then 'method_and_visual_structure_reference_only'
           else 'technical_evidence'
         end,
         'checked_on','2026-10-16'
       ) order by ts.source_key),'[]'::jsonb)
       from public.training_sources ts
       where ts.source_key in (select jsonb_array_elements_text(p->'source_keys'))
     ),
     'source_integration_note','Contenuti, casi, domande, attività e schemi sono originali SafetyTraining; le fonti sono usate per validazione normativa, evidenze tecniche e metodo.',
     'final_assessment',false
   ) as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null
from enriched
on conflict (learning_unit_id,version_number) do update
set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,sk.source_key,
       case
         when sk.source_key in ('mlps-asr-2025','normattiva-dlgs81-vigente','normattiva-dpr177-2011','mlps-di-segnaletica-stradale-2019') then 'normative_validation'
         when sk.source_key='piemonte-indicazioni-formazione-2025' then 'official_guidance_cross_check'
         when sk.source_key='rer-formazione-figure-prevenzione' then 'method_reference'
         else 'technical_evidence'
       end,
       case
         when sk.source_key='mlps-asr-2025' then 'Validazione di durata, finalità e contenuti minimi del Modulo B comune.'
         when sk.source_key='normattiva-dlgs81-vigente' then 'Validazione del quadro prevenzionistico e dei rischi trattati.'
         when sk.source_key='normattiva-dpr177-2011' then 'Disciplina specialistica per ambienti sospetti di inquinamento o confinati.'
         when sk.source_key='mlps-di-segnaletica-stradale-2019' then 'Disciplina delle attività lavorative in presenza di traffico veicolare.'
         when sk.source_key='piemonte-indicazioni-formazione-2025' then 'Controllo operativo dell’applicazione dell’Accordo 2025.'
         when sk.source_key='rer-formazione-figure-prevenzione' then 'Riferimento metodologico/visuale; claim normativi ricontrollati su fonti vigenti.'
         else 'Evidenza tecnica istituzionale pertinente alla Learning Unit.'
       end,
       date '2026-10-16','{}'::jsonb
from public.learning_units lu
join public.learning_unit_versions v on v.learning_unit_id=lu.id and v.version_number=2 and v.status='draft'
cross join lateral jsonb_array_elements_text(v.content->'source_keys') sk(source_key)
where lu.stable_key like 'rspp-aspp:rspp_aspp_b:ud%'
on conflict (learning_unit_id,source_key,purpose) do update
set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;